using UnityEngine;

/// <summary>
/// Entropy sling: burns down a fuse one activation at a time and fires a Cannonball
/// when it reaches the end, then starts over. The fuse counts activations rather
/// than seconds, so anything that activates the component advances it — ball hits,
/// a Capacitor discharge, or the twice-a-second ticks of its own burn, which is
/// what makes setting the Cannon alight worthwhile.
/// </summary>
public class CannonComponent : Bumper
{
    private const string cannonballDefinitionPath = "BallDefinitions/Cannonball";

    [Header("Cannon")]
    [Tooltip("Activations needed before the Cannon fires.")]
    [SerializeField] private int fuseLength = 15;
    [Tooltip("Ball created when the fuse finishes; loaded from Resources if empty.")]
    [SerializeField] private BallDefinition cannonballDefinition;
    [SerializeField] private Vector3 spawnOffset = new Vector3(0f, 0f, 0.5f);
    [Tooltip("Launch impulse given to the created Cannonball. Its scoring is "
        + "Kinetic, so it is worth firing hard.")]
    [SerializeField] private float launchImpulse = 12f;

    [SerializeField] private int fuseProgress;

    public int FuseProgress => fuseProgress;
    public int FuseLength => fuseLength;

    protected override void Awake()
    {
        base.Awake();

        if (cannonballDefinition == null)
        {
            cannonballDefinition = Resources.Load<BallDefinition>(cannonballDefinitionPath);
        }
    }

    protected override void OnCollisionEnter(Collision collision)
    {
        base.OnCollisionEnter(collision);

        if (collision.collider.GetComponent<Ball>() != null)
        {
            AdvanceFuse();
        }
    }

    public override void ActivateAsIfHit()
    {
        base.ActivateAsIfHit();
        AdvanceFuse();
    }

    private void AdvanceFuse()
    {
        fuseProgress++;
        if (fuseProgress < fuseLength)
        {
            return;
        }

        fuseProgress = 0;
        Fire();
    }

    private void Fire()
    {
        if (cannonballDefinition == null || cannonballDefinition.Prefab == null)
        {
            FireDebug.Log($"{name} fuse finished but no Cannonball definition to create");
            return;
        }

        Vector3 spawnPosition = transform.position + spawnOffset;
        GameObject cannonball = Instantiate(
            cannonballDefinition.Prefab, spawnPosition, Quaternion.identity);
        Ball.EnsureOwnMaterials(cannonball);

        Rigidbody body = cannonball.GetComponent<Rigidbody>();
        if (body != null)
        {
            body.AddForce(transform.forward * launchImpulse, ForceMode.Impulse);
        }

        ServiceLocator.Get<BallSpawner>()?.ActiveBalls.Add(cannonball);
        FireDebug.Log($"{name} fires a Cannonball at {spawnPosition}");
    }
}
